package com.cursorsize;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.TooltipOverlay;

/** Final pass: highlights and menus, then cursor, then readable tooltips. */
public class CursorForegroundOverlay extends Overlay
{
    private final CursorSizeOverlay cursor;
    private final TooltipOverlay tooltips;

    @Inject
    CursorForegroundOverlay(CursorSizeOverlay cursor, TooltipOverlay tooltips)
    {
        this.cursor = cursor;
        this.tooltips = tooltips;
        // TOOLTIP sorts after dynamic and fixed overlays. Lower priority draws last here.
        setPosition(OverlayPosition.TOOLTIP);
        setLayer(OverlayLayer.ALWAYS_ON_TOP);
        setPriority(-Float.MAX_VALUE);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        return cursor.renderFinal(graphics, () -> tooltips.render(graphics));
    }
}

package com.cursorsize;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import javax.imageio.ImageIO;
import javax.imageio.stream.MemoryCacheImageInputStream;

final class CursorImages
{
    private CursorImages() {}

    static BufferedImage read(InputStream input) throws IOException
    {
        // Explicit memory cache prevents ImageIO from creating temporary files.
        synchronized (ImageIO.class)
        {
            try (MemoryCacheImageInputStream imageInput = new MemoryCacheImageInputStream(input))
            {
                java.util.Iterator<javax.imageio.ImageReader> readers = ImageIO.getImageReaders(imageInput);
                if (!readers.hasNext()) { throw new IOException("cursor.png is not a supported image"); }
                javax.imageio.ImageReader reader = readers.next();
                try
                {
                    reader.setInput(imageInput);
                    return reader.read(0);
                }
                finally { reader.dispose(); }
            }
        }
    }

    static BufferedImage arrow()
    {
        BufferedImage image = new BufferedImage(24, 32, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        try
        {
            Polygon outline = new Polygon(new int[]{0, 0, 6, 11, 16, 11, 22},
                new int[]{0, 25, 20, 31, 29, 18, 18}, 7);
            g.setColor(Color.WHITE);
            g.fillPolygon(outline);
            g.setColor(Color.BLACK);
            g.drawPolygon(outline);
        }
        finally { g.dispose(); }
        return image;
    }

    static BufferedImage scale(BufferedImage source, int requestedPercent, boolean smooth)
    {
        int percent = Math.max(25, Math.min(400, requestedPercent));
        double ratio = Math.min(percent / 100.0, 512.0 / Math.max(source.getWidth(), source.getHeight()));
        int width = Math.max(1, (int) Math.round(source.getWidth() * ratio));
        int height = Math.max(1, (int) Math.round(source.getHeight() * ratio));
        BufferedImage result = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = result.createGraphics();
        try
        {
            g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, smooth
                ? RenderingHints.VALUE_INTERPOLATION_BICUBIC : RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
            g.drawImage(source, 0, 0, width, height, null);
        }
        finally { g.dispose(); }
        return result;
    }

    /** Inward outline: no padding, hotspot shift, or changes to the image's alpha mask. */
    static BufferedImage outline(BufferedImage source, int requestedThickness, Color color)
    {
        int thickness = Math.max(0, Math.min(5, requestedThickness));
        if (thickness == 0) { return source; }
        int width = source.getWidth();
        int height = source.getHeight();
        int[] pixels = source.getRGB(0, 0, width, height, null, 0, width);
        int[] result = pixels.clone();
        int rgb = (color == null ? Color.BLACK : color).getRGB() & 0x00ffffff;
        for (int y = 0; y < height; y++)
        {
            for (int x = 0; x < width; x++)
            {
                int index = y * width + x;
                if ((pixels[index] >>> 24) == 0) { continue; }
                boolean edge = false;
                for (int dy = -thickness; dy <= thickness && !edge; dy++)
                {
                    for (int dx = -thickness; dx <= thickness; dx++)
                    {
                        if (dx * dx + dy * dy > thickness * thickness) { continue; }
                        int nx = x + dx;
                        int ny = y + dy;
                        if (nx < 0 || ny < 0 || nx >= width || ny >= height
                            || (pixels[ny * width + nx] >>> 24) == 0)
                        {
                            edge = true;
                            break;
                        }
                    }
                }
                if (edge) { result[index] = (pixels[index] & 0xff000000) | rgb; }
            }
        }
        BufferedImage outlined = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        outlined.setRGB(0, 0, width, height, result, 0, width);
        return outlined;
    }

    static int legacyPercentage(BufferedImage source, int pixels)
    {
        int size = Math.max(8, Math.min(128, pixels));
        return Math.max(25, Math.min(400, (int) Math.round(100.0 * size
            / Math.max(source.getWidth(), source.getHeight()))));
    }

    // Padding prevents AWT from stretching small images to its native cursor size.
    static BufferedImage fitNativeCanvas(BufferedImage image, Dimension canvas)
    {
        if (canvas.width <= 0 || canvas.height <= 0)
        {
            throw new IllegalArgumentException("Custom cursors are unsupported by this display");
        }
        double ratio = Math.min(1.0, Math.min((double) canvas.width / image.getWidth(),
            (double) canvas.height / image.getHeight()));
        BufferedImage result = new BufferedImage(canvas.width, canvas.height, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = result.createGraphics();
        try
        {
            g.drawImage(image, 0, 0, Math.max(1, (int) Math.round(image.getWidth() * ratio)),
                Math.max(1, (int) Math.round(image.getHeight() * ratio)), null);
        }
        finally { g.dispose(); }
        return result;
    }
}

package com.cursorsize;

import java.awt.Color;
import net.runelite.client.config.*;

@ConfigGroup(CursorSizeConfig.GROUP)
public interface CursorSizeConfig extends Config
{
    String GROUP = "cursorsize";

    @ConfigItem(keyName = "style", name = "Cursor style", description = "Follow Custom Cursor uses the cursor selected in RuneLite's Custom Cursor settings, including custom images and equipped weapons. Keep that plugin disabled.", position = 0)
    default CursorStyle style() { return CursorStyle.FOLLOW_CUSTOM_CURSOR; }

    @Range(min = 25, max = 400)
    @ConfigItem(keyName = "scalePercent", name = "Cursor scale (%)", description = "25–400%. 100% is the original image size; 200% doubles it. Maximum rendered edge: 512 pixels.", position = 1)
    default int scalePercent() { return 150; }

    @ConfigItem(keyName = "smooth", name = "Smooth scaling", description = "Smooth image edges; disable for crisp pixel art.", position = 2)
    default boolean smooth() { return false; }
    @Range(min = 0, max = 5)
    @ConfigItem(keyName = "outlineThickness", name = "Outline thickness", description = "Outline width in pixels after scaling (0–5). 0 disables it. Drawn inside the visible edge to preserve the click point.", position = 3)
    default int outlineThickness() { return 0; }

    @ConfigItem(keyName = "outlineColor", name = "Outline colour", description = "Colour of the cursor outline. Set Outline thickness above 0 to enable it.", position = 4)
    default Color outlineColor() { return Color.BLACK; }
}

package com.cursorsize;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/** Software fallback for displays whose native cursor size is too small. */
@Singleton
public class CursorSizeOverlay extends Overlay
{
    private final Client client;
    private final TooltipManager tooltipManager;
    private volatile List<Tooltip> deferredTooltips = Collections.emptyList();
    private volatile BufferedImage image;
    private volatile long lastRenderNanos;

    @Inject
    CursorSizeOverlay(Client client, TooltipManager tooltipManager)
    {
        this.client = client;
        this.tooltipManager = tooltipManager;
        setPosition(OverlayPosition.DYNAMIC);
        // Capture tooltips before their normal pass; the final pass draws them after the cursor.
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(Float.MAX_VALUE);
    }

    void setImage(BufferedImage image)
    {
        this.image = image;
        lastRenderNanos = 0;
        if (image == null) { deferredTooltips = Collections.emptyList(); }
    }

    boolean isRendering(long now)
    {
        return image != null && lastRenderNanos != 0 && now - lastRenderNanos < 250_000_000L;
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (image != null && !tooltipManager.getTooltips().isEmpty())
        {
            List<Tooltip> captured = new ArrayList<>(deferredTooltips);
            captured.addAll(tooltipManager.getTooltips());
            deferredTooltips = captured;
            tooltipManager.clear();
        }
        return null;
    }

    void beginFrame()
    {
        deferredTooltips = Collections.emptyList();
    }

    Dimension renderFinal(Graphics2D graphics, Runnable drawTooltips)
    {
        List<Tooltip> captured = deferredTooltips;
        deferredTooltips = Collections.emptyList();
        try
        {
            return renderCursor(graphics);
        }
        finally
        {
            // Keep tooltip rendering in RuneLite, including components, colours and placement.
            tooltipManager.getTooltips().addAll(0, captured);
            if (!tooltipManager.getTooltips().isEmpty()) { drawTooltips.run(); }
        }
    }

    Dimension renderCursor(Graphics2D graphics)
    {
        BufferedImage current = image;
        Point mouse = client.getMouseCanvasPosition();
        if (current != null && mouse.getX() >= 0 && mouse.getY() >= 0
            && mouse.getX() < client.getCanvasWidth() && mouse.getY() < client.getCanvasHeight()
            && graphics.hitClip(mouse.getX(), mouse.getY(), current.getWidth(), current.getHeight()))
        {
            graphics.drawImage(current, mouse.getX(), mouse.getY(), null);
            lastRenderNanos = System.nanoTime();
        }
        return null;
    }
}

package com.cursorsize;

import com.google.inject.Provides;
import java.awt.Dimension;
import java.awt.Cursor;
import java.awt.Toolkit;
import java.awt.image.BufferedImage;
import java.io.InputStream;
import java.io.IOException;

import javax.inject.Inject;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import net.runelite.client.util.Filepath;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.customcursor.CustomCursor;
import net.runelite.client.plugins.customcursor.CustomCursorConfig;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientUI;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(name = "Custom Cursor Plus", internalName = "custom-cursor-plus", description = "Make your cursor bigger or smaller", tags = {"mouse", "accessibility"}, conflicts = {"Custom Cursor"})
public class CursorSizePlugin extends Plugin
{
    private static final Logger log = LoggerFactory.getLogger(CursorSizePlugin.class);
    @Inject private ClientUI clientUI;
    @Inject private CursorSizeConfig config;
    @Inject private Client client;
    @Inject private CursorSizeOverlay overlay;
    @Inject private CursorForegroundOverlay foregroundOverlay;
    @Inject private OverlayManager overlayManager;
    @Inject private ConfigManager configManager;
    @Inject private ClientThread clientThread;
    @Inject private ItemManager itemManager;
    private volatile boolean active;
    private volatile boolean loggedIn;
    private volatile BufferedImage weaponImage;
    // EDT-owned. Hide the native cursor only after a software frame really drew.
    private Cursor transparentCursor;
    private Cursor nativeCursor;
    private final Timer visibilityTimer = new Timer(50, event -> updateCanvasVisibility());

    @Provides
    CursorSizeConfig provideConfig(ConfigManager manager) { return manager.getConfig(CursorSizeConfig.class); }

    @Override
    protected void startUp()
    {
        active = true;
        loggedIn = client.getGameState() == GameState.LOGGED_IN;
        overlayManager.add(overlay);
        overlayManager.add(foregroundOverlay);
        updateCursor();
        refreshWeapon();
    }

    @Override
    protected void shutDown() throws Exception
    {
        active = false;
        overlayManager.remove(overlay);
        overlayManager.remove(foregroundOverlay);
        if (SwingUtilities.isEventDispatchThread()) { resetCursor(); }
        else { SwingUtilities.invokeAndWait(this::resetCursor); }
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if ((CursorSizeConfig.GROUP.equals(event.getGroup()) || "customcursor".equals(event.getGroup())) && active)
        {
            updateCursor();
            refreshWeapon();
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        loggedIn = event.getGameState() == GameState.LOGGED_IN;
        if (active)
        {
            updateCursor();
            refreshWeapon();
        }
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        if (active && event.getContainerId() == InventoryID.WORN) { refreshWeapon(); }
    }

    @Subscribe
    public void onBeforeRender(net.runelite.api.events.BeforeRender event)
    {
        overlay.beginFrame();
    }

    private CustomCursor selectedCursor()
    {
        return config.style().selectedCursor(configManager.getConfig(CustomCursorConfig.class).selectedCursor());
    }

    private void refreshWeapon()
    {
        clientThread.invokeLater(() ->
        {
            if (!active || selectedCursor() != CustomCursor.EQUIPPED_WEAPON) { return true; }
            ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
            Item weapon = equipment == null ? null : equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
            weaponImage = weapon == null || weapon.getQuantity() <= 0 ? null : itemManager.getImage(weapon.getId());
            updateCursor();
            return true;
        });
    }

    static boolean useOverlay(boolean loggedIn, BufferedImage image, Dimension nativeSize)
    {
        return loggedIn && (image.getWidth() > nativeSize.width || image.getHeight() > nativeSize.height);
    }

    private void updateCursor()
    {
        SwingUtilities.invokeLater(() ->
        {
            if (!active) { return; }
            try
            {
                CustomCursor selected = selectedCursor();
                BufferedImage source;
                if (selected == CustomCursor.CUSTOM_IMAGE)
                {
                    Filepath imagePath = getPluginDirectory().join("cursor.png");
                    try (InputStream input = imagePath.openInputStream())
                    {
                        source = CursorImages.read(input);
                    }
                    if (source == null) { throw new IOException("cursor.png is not a supported image"); }
                }
                else if (selected == CustomCursor.EQUIPPED_WEAPON)
                {
                    source = weaponImage == null ? CursorImages.arrow() : weaponImage;
                }
                else { source = selected == null ? CursorImages.arrow() : selected.getCursorImage(); }
                int percentage = config.scalePercent();
                // Preserve the old apparent size once, without treating pixel values as percentages.
                if (!"true".equals(configManager.getConfiguration(CursorSizeConfig.GROUP, "percentageMigrated")))
                {
                    String legacy = configManager.getConfiguration(CursorSizeConfig.GROUP, "size");
                    if (legacy != null && (selected != CustomCursor.EQUIPPED_WEAPON || weaponImage != null))
                    {
                        try
                        {
                            // RuneLite writes defaults before startup, so a null check is insufficient.
                            if (percentage == 150) { percentage = CursorImages.legacyPercentage(source, Integer.parseInt(legacy)); }
                            configManager.setConfiguration(CursorSizeConfig.GROUP, "percentageMigrated", true);
                            configManager.setConfiguration(CursorSizeConfig.GROUP, "scalePercent", percentage);
                        }
                        catch (NumberFormatException e)
                        {
                            log.warn("Ignoring invalid legacy cursor size");
                        }
                    }
                }
                BufferedImage scaled = CursorImages.scale(source, percentage, config.smooth());
                scaled = CursorImages.outline(scaled, config.outlineThickness(), config.outlineColor());
                Dimension nativeSize = Toolkit.getDefaultToolkit().getBestCursorSize(scaled.getWidth(), scaled.getHeight());
                clientUI.setCursor(CursorImages.fitNativeCanvas(scaled, nativeSize), "Custom Cursor Plus");
                nativeCursor = clientUI.getDefaultCursor();
                log.info("Custom Cursor Plus: style={}, selected={}, size={}x{}, native={}x{}, loggedIn={}, software={}",
                    config.style(), selected, scaled.getWidth(), scaled.getHeight(), nativeSize.width,
                    nativeSize.height, loggedIn, useOverlay(loggedIn, scaled, nativeSize));
                if (useOverlay(loggedIn, scaled, nativeSize))
                {
                    overlay.setImage(scaled);
                    BufferedImage blank = new BufferedImage(nativeSize.width, nativeSize.height, BufferedImage.TYPE_INT_ARGB);
                    transparentCursor = Toolkit.getDefaultToolkit().createCustomCursor(blank,
                        new java.awt.Point(0, 0), "Custom Cursor Plus overlay");
                    client.getCanvas().setCursor(nativeCursor);
                    visibilityTimer.start();
                }
                else
                {
                    visibilityTimer.stop();
                    transparentCursor = null;
                    overlay.setImage(null);
                    client.getCanvas().setCursor(nativeCursor);
                }
            }
            catch (IOException | RuntimeException e)
            {
                log.warn("Unable to apply Custom Cursor Plus; restoring the system cursor", e);
                resetCursor();
            }
        });
    }

    private void resetCursor()
    {
        visibilityTimer.stop();
        transparentCursor = null;
        nativeCursor = null;
        overlay.setImage(null);
        client.getCanvas().setCursor(null);
        clientUI.resetCursor();
    }

    private void updateCanvasVisibility()
    {
        Cursor desired = active && loggedIn && overlay.isRendering(System.nanoTime()) ? transparentCursor : nativeCursor;
        if (client.getCanvas().getCursor() != desired) { client.getCanvas().setCursor(desired); }
    }
}

package com.cursorsize;

import net.runelite.client.plugins.customcursor.CustomCursor;

public enum CursorStyle
{
    FOLLOW_CUSTOM_CURSOR("Follow Custom Cursor", null),
    ARROW("Arrow", null),
    GOLD("RS3 Gold", CustomCursor.RS3_GOLD),
    SILVER("RS3 Silver", CustomCursor.RS3_SILVER),
    DAGGER("Dragon Dagger", CustomCursor.DRAGON_DAGGER),
    POISON_DAGGER("Dragon Dagger (p)", CustomCursor.DRAGON_DAGGER_POISON),
    TROUT("Trout", CustomCursor.TROUT),
    SCIMITAR("Dragon Scimitar", CustomCursor.DRAGON_SCIMITAR),
    CUSTOM_IMAGE("Custom Image", null);

    private final String label;
    final CustomCursor builtIn;

    CursorStyle(String label, CustomCursor builtIn)
    {
        this.label = label;
        this.builtIn = builtIn;
    }

    @Override
    public String toString() { return label; }

    CustomCursor selectedCursor(CustomCursor customCursor)
    {
        if (this == FOLLOW_CUSTOM_CURSOR) { return customCursor; }
        if (this == CUSTOM_IMAGE) { return CustomCursor.CUSTOM_IMAGE; }
        return builtIn;
    }
}

package com.cursorsize;

import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import javax.imageio.ImageIO;
import javax.imageio.stream.MemoryCacheImageOutputStream;
import org.junit.Test;
import static org.junit.Assert.*;

public class CursorImageLoadingTest
{
    @Test public void decodesPngWithTransparencyUsingMemoryStreams() throws IOException
    {
        BufferedImage source = new BufferedImage(3, 2, BufferedImage.TYPE_INT_ARGB);
        source.setRGB(1, 0, 0xffff0000);
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        try (MemoryCacheImageOutputStream output = new MemoryCacheImageOutputStream(bytes))
        {
            assertTrue(ImageIO.write(source, "png", output));
        }
        BufferedImage decoded = CursorImages.read(new ByteArrayInputStream(bytes.toByteArray()));
        assertEquals(3, decoded.getWidth());
        assertEquals(2, decoded.getHeight());
        assertEquals(0xffff0000, decoded.getRGB(1, 0));
        assertEquals(0, decoded.getRGB(0, 0));
    }

    @Test(expected = IOException.class)
    public void rejectsInvalidImage() throws IOException
    {
        CursorImages.read(new ByteArrayInputStream(new byte[]{1, 2, 3}));
    }
}

package com.cursorsize;

import java.awt.Dimension;
import java.awt.image.BufferedImage;
import org.junit.Test;
import static org.junit.Assert.*;

public class CursorImagesTest
{
    @Test public void scalesUpAndDownWithoutChangingAspectRatio()
    {
        BufferedImage source = new BufferedImage(16, 32, BufferedImage.TYPE_INT_ARGB);
        BufferedImage large = CursorImages.scale(source, 200, false);
        assertEquals(32, large.getWidth());
        assertEquals(64, large.getHeight());
        BufferedImage small = CursorImages.scale(source, 25, true);
        assertEquals(4, small.getWidth());
        assertEquals(8, small.getHeight());
    }

    @Test public void preservesTransparencyAndPadsWithoutEnlarging()
    {
        BufferedImage source = new BufferedImage(8, 8, BufferedImage.TYPE_INT_ARGB);
        source.setRGB(0, 0, 0xffff0000);
        BufferedImage padded = CursorImages.fitNativeCanvas(source, new Dimension(32, 32));
        assertEquals(0xffff0000, padded.getRGB(0, 0));
        assertEquals(0, padded.getRGB(8, 8));
        assertEquals(0, padded.getRGB(31, 31));
    }

    @Test public void limitsOversizedSettingsAndFitsNativeLimits()
    {
        BufferedImage source = new BufferedImage(16, 32, BufferedImage.TYPE_INT_ARGB);
        assertEquals(128, CursorImages.scale(source, Integer.MAX_VALUE, false).getHeight());
        assertEquals(8, CursorImages.scale(source, -1, false).getHeight());
        BufferedImage fitted = CursorImages.fitNativeCanvas(source, new Dimension(8, 8));
        assertEquals(8, fitted.getWidth());
        assertEquals(8, fitted.getHeight());
    }

    @Test public void originalSizeAndFractionalScale()
    {
        BufferedImage source = new BufferedImage(17, 31, BufferedImage.TYPE_INT_ARGB);
        source.setRGB(0, 0, 0xffff0000);
        BufferedImage original = CursorImages.scale(source, 100, false);
        assertEquals(17, original.getWidth());
        assertEquals(31, original.getHeight());
        assertEquals(0xffff0000, original.getRGB(0, 0));
        BufferedImage scaled = CursorImages.scale(source, 150, true);
        assertEquals(26, scaled.getWidth());
        assertEquals(47, scaled.getHeight());
    }

    @Test public void limitsLargeCustomImagesAndKeepsTinyImagesValid()
    {
        BufferedImage large = new BufferedImage(1024, 512, BufferedImage.TYPE_INT_ARGB);
        BufferedImage scaled = CursorImages.scale(large, 400, false);
        assertEquals(512, scaled.getWidth());
        assertEquals(256, scaled.getHeight());
        BufferedImage tiny = CursorImages.scale(new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB), 25, false);
        assertEquals(1, tiny.getWidth());
        assertEquals(1, tiny.getHeight());
    }

    @Test public void migratesLegacyPixelsToPercentage()
    {
        assertEquals(150, CursorImages.legacyPercentage(CursorImages.arrow(), 48));
        assertEquals(400, CursorImages.legacyPercentage(CursorImages.arrow(), 128));
        assertEquals(25, CursorImages.legacyPercentage(CursorImages.arrow(), 8));
        assertEquals(100, CursorImages.legacyPercentage(new BufferedImage(48, 24, BufferedImage.TYPE_INT_ARGB), 48));
    }

    @Test(expected = IllegalArgumentException.class)
    public void rejectsUnsupportedNativeCursors()
    {
        CursorImages.fitNativeCanvas(CursorImages.arrow(), new Dimension(0, 0));
    }
}

package com.cursorsize;

import java.awt.Color;
import java.awt.image.BufferedImage;
import org.junit.Test;
import static org.junit.Assert.*;

public class CursorOutlineTest
{
    private BufferedImage square()
    {
        BufferedImage image = new BufferedImage(9, 9, BufferedImage.TYPE_INT_ARGB);
        for (int y = 1; y < 8; y++)
        {
            for (int x = 1; x < 8; x++) { image.setRGB(x, y, Color.RED.getRGB()); }
        }
        return image;
    }

    @Test public void disabledOutlineLeavesOriginalUntouched()
    {
        BufferedImage source = square();
        assertSame(source, CursorImages.outline(source, 0, Color.BLUE));
        assertSame(source, CursorImages.outline(source, -1, Color.BLUE));
    }

    @Test public void coloursEdgesWithoutMovingImageOrChangingInterior()
    {
        BufferedImage source = square();
        BufferedImage result = CursorImages.outline(source, 1, Color.BLUE);
        assertEquals(9, result.getWidth());
        assertEquals(9, result.getHeight());
        assertEquals(Color.BLUE.getRGB(), result.getRGB(1, 4));
        assertEquals(Color.RED.getRGB(), result.getRGB(2, 4));
        assertEquals(Color.RED.getRGB(), result.getRGB(4, 4));
        assertEquals(0, result.getRGB(0, 4));
        assertEquals(Color.RED.getRGB(), source.getRGB(1, 4));
    }

    @Test public void thickerOutlineReachesFurtherInside()
    {
        BufferedImage result = CursorImages.outline(square(), 2, Color.GREEN);
        assertEquals(Color.GREEN.getRGB(), result.getRGB(2, 4));
        assertEquals(Color.RED.getRGB(), result.getRGB(3, 4));
    }

    @Test public void preservesAntialiasingAndOutlinesHoles()
    {
        BufferedImage source = square();
        source.setRGB(1, 4, 0x80ff0000);
        source.setRGB(4, 4, 0);
        BufferedImage result = CursorImages.outline(source, 1, Color.WHITE);
        assertEquals(0x80ffffff, result.getRGB(1, 4));
        assertEquals(0, result.getRGB(4, 4));
        assertEquals(Color.WHITE.getRGB(), result.getRGB(4, 3));
    }

    @Test public void handlesImageBoundaryTinyAndEmptyImages()
    {
        BufferedImage tiny = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
        tiny.setRGB(0, 0, Color.RED.getRGB());
        assertEquals(Color.BLACK.getRGB(), CursorImages.outline(tiny, 5, null).getRGB(0, 0));
        assertEquals(0, CursorImages.outline(new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB), 5, Color.BLUE).getRGB(0, 0));
    }

    @Test public void clampsThicknessToFivePixels()
    {
        BufferedImage source = square();
        BufferedImage expected = CursorImages.outline(source, 5, Color.BLUE);
        BufferedImage actual = CursorImages.outline(source, Integer.MAX_VALUE, Color.BLUE);
        assertArrayEquals(expected.getRGB(0, 0, 9, 9, null, 0, 9), actual.getRGB(0, 0, 9, 9, null, 0, 9));
    }
}

package com.cursorsize;

import java.awt.Dimension;
import java.awt.image.BufferedImage;
import net.runelite.client.plugins.customcursor.CustomCursor;
import org.junit.Test;
import static org.junit.Assert.*;

public class CursorSelectionTest
{
    @Test public void neverHidesNativeCursorOutsideLoggedInState()
    {
        BufferedImage image = CursorImages.scale(CursorImages.arrow(), 400, false);
        assertFalse(CursorSizePlugin.useOverlay(false, image, new Dimension(32, 32)));
        assertTrue(CursorSizePlugin.useOverlay(true, image, new Dimension(32, 32)));
        assertFalse(CursorSizePlugin.useOverlay(true, image, new Dimension(128, 128)));
    }

    @Test public void followsEveryCustomCursorSelection()
    {
        for (CustomCursor cursor : CustomCursor.values())
        {
            assertSame(cursor, CursorStyle.FOLLOW_CUSTOM_CURSOR.selectedCursor(cursor));
        }
        assertSame(CustomCursor.CUSTOM_IMAGE, CursorStyle.CUSTOM_IMAGE.selectedCursor(CustomCursor.RS3_GOLD));
        assertNull(CursorStyle.ARROW.selectedCursor(CustomCursor.RS3_GOLD));
    }

    @Test public void everyBuiltInCursorCanGrowAndShrink()
    {
        for (CursorStyle style : CursorStyle.values())
        {
            if (style.builtIn == null) { continue; }
            assertSame(style.builtIn, style.selectedCursor(CustomCursor.RS3_SILVER));
            BufferedImage source = style.builtIn.getCursorImage();
            for (int size : new int[]{25, 100, 200, 400})
            {
                BufferedImage scaled = CursorImages.scale(source, size, false);
                assertEquals((int) Math.round(Math.max(source.getWidth(), source.getHeight()) * size / 100.0), Math.max(scaled.getWidth(), scaled.getHeight()));
                boolean visible = false;
                for (int y = 0; y < scaled.getHeight(); y++)
                {
                    for (int x = 0; x < scaled.getWidth(); x++)
                    {
                        visible |= (scaled.getRGB(x, y) >>> 24) != 0;
                    }
                }
                assertTrue(style + " must remain visible at " + size, visible);
            }
        }
    }
}

